**modules/rds/main.tf**
```hcl
resource "aws_db_instance" "postgres" {
  identifier     = var.instance_identifier
  engine         = "postgres"
  engine_version = var.engine_version
  instance_class = var.instance_class

  # Storage
  allocated_storage = var.allocated_storage
  storage_type      = "gp3"
  storage_encrypted = var.enable_encryption

  # Credentials
  db_name  = var.database_name
  username = var.master_username
  password = var.master_password

  # Availability & Backup
  multi_az                   = var.multi_az
  backup_retention_period    = var.backup_retention_days
  backup_window              = "03:00-04:00"
  maintenance_window         = "mon:04:00-mon:05:00"
  copy_tags_to_snapshot      = true
  delete_automated_backups   = !var.enable_deletion_protection

  # Security
  db_subnet_group_name            = var.db_subnet_group_name
  vpc_security_group_ids           = var.vpc_security_group_ids
  publicly_accessible              = var.publicly_accessible
  deletion_protection              = var.enable_deletion_protection
  enabled_cloudwatch_logs_exports  = ["postgresql"]
  monitoring_interval              = 60
  monitoring_role_arn              = aws_iam_role.rds_monitoring.arn
  enable_iam_database_authentication = true

  # Performance Insights
  performance_insights_enabled          = var.multi_az ? true : false
  performance_insights_retention_period = 7

  skip_final_snapshot       = !var.enable_deletion_protection
  final_snapshot_identifier = "${var.instance_identifier}-final-snapshot-${formatdate("YYYY-MM-DD-hhmm", timestamp())}"

  tags = merge(
    var.tags,
    {
      Name        = var.instance_identifier
      Environment = var.environment
    }
  )
}

# RDS monitoring role
resource "aws_iam_role" "rds_monitoring" {
  name = "${var.instance_identifier}-monitoring-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "monitoring.rds.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = var.tags
}

resource "aws_iam_role_policy_attachment" "rds_monitoring" {
  role       = aws_iam_role.rds_monitoring.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonRDSEnhancedMonitoringRole"
}
