**modules/iam/main.tf**
```hcl
# Service account user
resource "aws_iam_user" "service" {
  name = var.service_account_name

  tags = merge(
    var.tags,
    {
      Name        = var.service_account_name
      Environment = var.environment
    }
  )
}

# Access key for programmatic access (store securely!)
resource "aws_iam_access_key" "service" {
  user = aws_iam_user.service.name
}

# IAM role for OIDC trust (alternative for prod)
resource "aws_iam_role" "service_oidc" {
  name = "${var.service_account_name}-oidc"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          # This should be updated with actual OIDC provider ARN
          AWS = aws_iam_user.service.arn
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = var.tags
}

# S3 access policy - least privilege
resource "aws_iam_policy" "s3_access" {
  name        = "${var.service_account_name}-s3-policy"
  description = "S3 access policy for ${var.service_account_name}"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "ListBucket"
        Effect = "Allow"
        Action = [
          "s3:GetBucketVersioning",
          "s3:ListBucket"
        ]
        Resource = var.s3_bucket_arn
      },
      {
        Sid    = "GetPutDeleteObject"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:GetObjectVersion",
          "s3:PutObject",
          "s3:DeleteObject"
        ]
        Resource = var.s3_bucket_objects_arn
      }
    ]
  })
}

# RDS access policy - least privilege
resource "aws_iam_policy" "rds_access" {
  count       = var.allow_rds_connect ? 1 : 0
  name        = "${var.service_account_name}-rds-policy"
  description = "RDS access policy for ${var.service_account_name}"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "IAMDatabaseAuth"
        Effect = "Allow"
        Action = [
          "rds-db:connect"
        ]
        Resource = "${var.rds_instance_arn}/*"
      },
      {
        Sid    = "DescribeDBInstance"
        Effect = "Allow"
        Action = [
          "rds:DescribeDBInstances"
        ]
        Resource = var.rds_instance_arn
      }
    ]
  })
}

# Attach policies to user
resource "aws_iam_user_policy_attachment" "s3" {
  user       = aws_iam_user.service.name
  policy_arn = aws_iam_policy.s3_access.arn
}

resource "aws_iam_user_policy_attachment" "rds" {
  count      = var.allow_rds_connect ? 1 : 0
  user       = aws_iam_user.service.name
  policy_arn = aws_iam_policy.rds_access[0].arn
}

# Attach policies to OIDC role
resource "aws_iam_role_policy_attachment" "oidc_s3" {
  role       = aws_iam_role.service_oidc.name
  policy_arn = aws_iam_policy.s3_access.arn
}

resource "aws_iam_role_policy_attachment" "oidc_rds" {
  count      = var.allow_rds_connect ? 1 : 0
  role       = aws_iam_role.service_oidc.name
  policy_arn = aws_iam_policy.rds_access[0].arn
}
